#include <iostream>
#include <stdexcept>
using namespace std;

class Bird {
public:
    virtual void fly() {
        cout << "Flying through the air" << endl;
    }
    virtual ~Bird() = default;
};

class Sparrow : public Bird {
    // fine, sparrows do fly
};

class Penguin : public Bird {
public:
    void fly() override {
        throw runtime_error("Penguins can't fly");
    } // forced override, the contract every Bird promised is now broken for this one
};

int main() {
    Sparrow sparrow;
    sparrow.fly(); // Flying through the air

    Penguin penguin;
    try {
        penguin.fly();
    } catch (const runtime_error& e) {
        cout << "Penguins can't fly" << endl;
    }
    return 0;
}

